/**
 * Custom Door Designer - Optimized Shopify Integration
 * Vanilla JavaScript with Three.js for maximum performance
 * No React dependencies - designed for fast loading on Shopify
 */

(function () {
    'use strict';

    // Configuration defaults
    const DEFAULT_CONFIG = {
        width: 800,
        height: 2100,
        thickness: 40,
        mainHeight: 2100,
        preset: 'single',
        panelType: 'STANDARD_12MM',
        material: 'oak',
        finish: 'natural',
        color: 'natural_wood',
        borderStyle: 'simple',
        borderHeight: { top: 0, bottom: 0 }
    };

    // Dark gray-brown color palette for panels
    const PANEL_COLORS = {
        'STANDARD_12MM': 0x4A3C31,
        'REEDED_19MM': 0x3E3128,
        'MELAMINE_18MM': 0x5C4A3D,
        default: 0x4A3C31
    };

    // Material color mapping
    const DOOR_COLORS = {
        natural_wood: 0xD4A574,
        light: 0xF5DEB3,
        medium: 0xD2691E,
        dark: 0x8B4513,
        white: 0xFFFFFF,
        black: 0x1a1a1a,
        grey: 0x808080
    };

    const MATERIAL_TINTS = {
        oak: 0xD4A574,
        pine: 0xE3C79E,
        walnut: 0x5C4033,
        mahogany: 0xC04000,
        maple: 0xE9C2A6,
        cherry: 0xC95A49
    };

    class DoorConfigurator {
        constructor(containerId, options = {}) {
            this.container = document.getElementById(containerId);
            if (!this.container) {
                console.error('DoorConfigurator: Container not found:', containerId);
                return;
            }

            this.config = { ...DEFAULT_CONFIG, ...options };
            this.scene = null;
            this.camera = null;
            this.renderer = null;
            this.doorGroup = null;
            this.woodTexture = null;
            this.animationId = null;
            this.isInitialized = false;
            this.isLoading = false;

            // Debounce update function for performance
            this.debouncedUpdate = this.debounce(this.updateDoor.bind(this), 100);

            // Lazy load when visible
            this.setupLazyLoading();
        }

        setupLazyLoading() {
            if ('IntersectionObserver' in window) {
                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            this.init();
                            observer.disconnect();
                        }
                    });
                }, { rootMargin: '200px' }); // Start loading 200px before it comes into view
                observer.observe(this.container);
            } else {
                // Fallback for older browsers
                this.init();
            }
        }

        debounce(func, wait) {
            let timeout;
            return function executedFunction(...args) {
                const later = () => {
                    clearTimeout(timeout);
                    func(...args);
                };
                clearTimeout(timeout);
                timeout = setTimeout(later, wait);
            };
        }

        async init() {
            if (this.isInitialized || this.isLoading) return;
            this.isLoading = true;

            // Check if Three.js is loaded
            if (typeof THREE === 'undefined') {
                try {
                    await this.loadThreeJS();
                } catch (error) {
                    console.error('Failed to load Three.js:', error);
                    this.container.querySelector('.door-3d-loading p').textContent = 'Error loading 3D engine.';
                    return;
                }
            }

            this.setupScene();
            await this.loadTextures();
            this.createDoor();
            this.animate();
            this.isInitialized = true;
            this.isLoading = false;

            // Dispatch ready event
            this.container.dispatchEvent(new CustomEvent('doorConfiguratorReady', { detail: this }));
        }

        loadThreeJS() {
            return new Promise((resolve, reject) => {
                if (typeof THREE !== 'undefined') {
                    resolve();
                    return;
                }

                const script = document.createElement('script');
                script.src = 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.min.js';
                script.async = true;
                script.onload = resolve;
                script.onerror = reject;
                document.head.appendChild(script);
            });
        }

        setupScene() {
            const width = this.container.clientWidth;
            const height = this.container.clientHeight || 500;

            // Scene
            this.scene = new THREE.Scene();
            this.scene.background = new THREE.Color(0xf5f5f5);

            // Camera
            this.camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 100);
            this.camera.position.set(0, 0, 4);

            // Renderer with performance optimizations
            this.renderer = new THREE.WebGLRenderer({
                antialias: true,
                powerPreference: 'high-performance'
            });
            this.renderer.setSize(width, height);
            this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
            this.renderer.shadowMap.enabled = true;
            this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
            this.container.appendChild(this.renderer.domElement);

            // Lighting
            const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
            this.scene.add(ambientLight);

            const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
            directionalLight.position.set(5, 10, 7);
            directionalLight.castShadow = true;
            this.scene.add(directionalLight);

            // Handle resize
            window.addEventListener('resize', this.handleResize.bind(this));
        }

        handleResize() {
            const width = this.container.clientWidth;
            const height = this.container.clientHeight || 500;

            this.camera.aspect = width / height;
            this.camera.updateProjectionMatrix();
            this.renderer.setSize(width, height);
        }

        loadTextures() {
            return new Promise((resolve) => {
                const textureLoader = new THREE.TextureLoader();

                // Try to load wood texture, fallback to solid color if unavailable
                textureLoader.load(
                    '/textures/wood.jpg',
                    (texture) => {
                        texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
                        texture.repeat.set(2, 4);
                        this.woodTexture = texture;
                        resolve();
                    },
                    undefined,
                    () => {
                        // Texture failed to load, continue without it
                        this.woodTexture = null;
                        resolve();
                    }
                );
            });
        }

        getDoorColor() {
            const { material, finish, color } = this.config;
            let baseColor = DOOR_COLORS[color] || DOOR_COLORS.natural_wood;

            if (finish === 'painted') {
                return baseColor;
            } else if (finish === 'stained' || finish === 'varnished') {
                return color === 'natural_wood' ? (MATERIAL_TINTS[material] || baseColor) : baseColor;
            }
            return MATERIAL_TINTS[material] || baseColor;
        }

        getPanelColor() {
            const { panelType } = this.config;
            return PANEL_COLORS[panelType] || PANEL_COLORS.default;
        }

        createDoor() {
            if (this.doorGroup) {
                this.scene.remove(this.doorGroup);
                this.disposeMeshes(this.doorGroup);
            }

            this.doorGroup = new THREE.Group();

            const { width, height, thickness, preset } = this.config;
            const w = width / 1000;
            const h = height / 1000;
            const t = thickness / 1000;

            const doorColor = this.getDoorColor();
            const panelColor = this.getPanelColor();

            if (preset === 'double') {
                this.createDoorLeaf(w / 2, h, t, [-w / 4 - 0.005, 0, 0], doorColor, panelColor, false);
                this.createDoorLeaf(w / 2, h, t, [w / 4 + 0.005, 0, 0], doorColor, panelColor, true);
            } else {
                this.createDoorLeaf(w, h, t, [0, 0, 0], doorColor, panelColor, false);
            }

            this.scene.add(this.doorGroup);
        }

        createDoorLeaf(w, h, t, position, doorColor, panelColor, mirrorHandle) {
            const leafGroup = new THREE.Group();
            leafGroup.position.set(...position);

            // Main door frame
            const frameGeometry = new THREE.BoxGeometry(w, h, t);
            const frameMaterial = new THREE.MeshStandardMaterial({
                map: this.woodTexture,
                color: doorColor
            });
            const frame = new THREE.Mesh(frameGeometry, frameMaterial);
            frame.castShadow = true;
            frame.receiveShadow = true;
            leafGroup.add(frame);

            // Add panel
            this.addPanel(leafGroup, w, h, t, panelColor);

            // Add handle
            this.addHandle(leafGroup, w, t, mirrorHandle);

            this.doorGroup.add(leafGroup);
        }

        addPanel(group, w, h, t, panelColor) {
            const borderWidth = 0.075;
            const innerWidth = w - borderWidth * 2;
            const innerHeight = h - borderWidth * 2;

            // Panel
            const panelGeometry = new THREE.BoxGeometry(innerWidth - 0.04, innerHeight - 0.04, 0.012);
            const panelMaterial = new THREE.MeshStandardMaterial({
                color: panelColor,
                roughness: 0.85
            });
            const panel = new THREE.Mesh(panelGeometry, panelMaterial);
            panel.position.set(0, 0, t / 2 + 0.005);
            panel.castShadow = true;
            group.add(panel);
        }

        addHandle(group, w, t, mirror) {
            const handleX = mirror ? -w * 0.35 : w * 0.35;
            const handleMaterial = new THREE.MeshStandardMaterial({
                color: 0x3a3a3a,
                metalness: 0.9,
                roughness: 0.15
            });

            // Handle cylinder
            const cylinderGeometry = new THREE.CylinderGeometry(0.012, 0.012, 0.08, 16);
            const cylinder = new THREE.Mesh(cylinderGeometry, handleMaterial);
            cylinder.position.set(handleX, 0, t / 2 + 0.02);
            cylinder.castShadow = true;
            group.add(cylinder);

            // Handle knob
            const sphereGeometry = new THREE.SphereGeometry(0.02, 16, 16);
            const sphere = new THREE.Mesh(sphereGeometry, handleMaterial);
            sphere.position.set(handleX, 0, t / 2 + 0.05);
            sphere.castShadow = true;
            group.add(sphere);
        }

        disposeMeshes(object) {
            object.traverse((child) => {
                if (child.isMesh) {
                    if (child.geometry) child.geometry.dispose();
                    if (child.material) {
                        if (Array.isArray(child.material)) {
                            child.material.forEach(m => m.dispose());
                        } else {
                            child.material.dispose();
                        }
                    }
                }
            });
        }

        animate() {
            this.animationId = requestAnimationFrame(this.animate.bind(this));

            // Gentle rotation animation
            if (this.doorGroup) {
                this.doorGroup.rotation.y = Math.sin(Date.now() * 0.0002) * 0.05;
            }

            this.renderer.render(this.scene, this.camera);
        }

        updateConfig(newConfig) {
            this.config = { ...this.config, ...newConfig };
            this.debouncedUpdate();
        }

        updateDoor() {
            this.createDoor();
        }

        destroy() {
            if (this.animationId) {
                cancelAnimationFrame(this.animationId);
            }

            window.removeEventListener('resize', this.handleResize.bind(this));

            if (this.doorGroup) {
                this.disposeMeshes(this.doorGroup);
                this.scene.remove(this.doorGroup);
            }

            if (this.renderer) {
                this.renderer.dispose();
                this.container.removeChild(this.renderer.domElement);
            }

            if (this.woodTexture) {
                this.woodTexture.dispose();
            }
        }

        // Public API for Shopify integration
        getConfig() {
            return { ...this.config };
        }

        setWidth(value) {
            this.updateConfig({ width: parseInt(value, 10) });
        }

        setHeight(value) {
            this.updateConfig({ height: parseInt(value, 10), mainHeight: parseInt(value, 10) });
        }

        setPreset(value) {
            this.updateConfig({ preset: value });
        }

        setPanelType(value) {
            this.updateConfig({ panelType: value });
        }

        setMaterial(value) {
            this.updateConfig({ material: value });
        }

        setFinish(value) {
            this.updateConfig({ finish: value });
        }

        setColor(value) {
            this.updateConfig({ color: value });
        }
    }

    // Export to global scope for Shopify
    window.DoorConfigurator = DoorConfigurator;

    // Auto-initialize if data attribute is present
    document.addEventListener('DOMContentLoaded', function () {
        const autoInitContainers = document.querySelectorAll('[data-door-configurator]');
        autoInitContainers.forEach(function (container) {
            const options = container.dataset.doorConfiguratorOptions;
            new DoorConfigurator(container.id, options ? JSON.parse(options) : {});
        });
    });

})();
